/* Generated settings required by FFmpeg's public headers. */
#ifndef AVUTIL_AVCONFIG_H
#define AVUTIL_AVCONFIG_H

/* AnimaX's supported Windows targets are little-endian. */
#define AV_HAVE_BIGENDIAN 0

/* Keep public header helpers on the portable unaligned-access path. */
#define AV_HAVE_FAST_UNALIGNED 0

#endif /* AVUTIL_AVCONFIG_H */
